using EventLensAI.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class AnalyticsRecordConfiguration:IEntityTypeConfiguration<AnalyticsRecord>{public void Configure(EntityTypeBuilder<AnalyticsRecord>b){b.ToTable("analytics_records");b.ConfigureBase();b.Property(x=>x.Metric).HasConversion<string>().HasMaxLength(50);b.Property(x=>x.SessionKeyHash).HasMaxLength(64);b.Property(x=>x.DeviceType).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.Browser).HasMaxLength(80);b.Property(x=>x.OperatingSystem).HasMaxLength(80);b.Property(x=>x.Country).HasMaxLength(100);b.Property(x=>x.City).HasMaxLength(100);b.Property(x=>x.DimensionsJson).HasColumnType("nvarchar(max)");b.HasIndex(x=>new{x.OrganizationId,x.OccurredAt,x.Metric});b.HasIndex(x=>new{x.EventId,x.OccurredAt,x.Metric});b.HasIndex(x=>new{x.PhotoId,x.Metric});}}
internal sealed class AnalyticsDailyAggregateConfiguration:IEntityTypeConfiguration<AnalyticsDailyAggregate>{public void Configure(EntityTypeBuilder<AnalyticsDailyAggregate>b){b.ToTable("analytics_daily_aggregates");b.ConfigureBase();b.Property(x=>x.Metric).HasConversion<string>().HasMaxLength(50);b.HasIndex(x=>new{x.OrganizationId,x.Date,x.Metric,x.EventId,x.TemplateId,x.PhotographerId}).IsUnique();b.HasIndex(x=>new{x.EventId,x.Date,x.Metric});}}
